INSERT INTO "provincial_messages" VALUES(1,'Test sapaan','Sapaan limit','sapaan-provinsial/a8x1BZAFU2O5BtO04DVdDG2fNDDXWSunoLVXD3vz.jpg','Br. Agustinus Giwal Santoso, FIC','2026-10-07 16:15:18',0,1,'2026-10-07 16:15:18','2026-10-20 02:18:34',NULL,'sapaan',NULL,NULL);
INSERT INTO "provincial_messages" VALUES(2,'Test Sapaan Provinsial Langsung','Ini adalah test sapaan provinsial terbaru dari Super Admin. Pesan ini harus langsung muncul pada halaman Sapaan Provinsial di sisi user setelah publikasi.',NULL,'Br. Test Provinsial, FIC','2026-10-08 14:04:01',0,1,'2026-10-08 14:04:01','2026-10-20 02:20:34',NULL,'sapaan',NULL,NULL);
INSERT INTO "provincial_messages" VALUES(3,'Ajakan santapan sabda','Hallo gays, jangan lupa sarapan pagi ini dengan santapan sabda. Temukan makna dari ayat kitab suci yang bermakna. Maaf ada Typo','sapaan/NfMqNEYQwJxQQlblFLVQ1HXEyI1NQbw8RWd4cr8R.jpg','Br. Agustinus Giwal Santoso, FIC','2026-10-20 02:14:03',0,1,'2026-10-20 02:14:03','2026-10-20 02:18:34',NULL,'sapaan','Pemimpin Provinsial FIC Indonesia',NULL);
INSERT INTO "provincial_messages" VALUES(4,'Pertemuan Pleno','Mohhon para bruder mambawa Brevir atau jika tidak maka wajib menginstall E-Katolik untuk keperluan berdoa bersama',NULL,'Br. Andrias Purwanto, FIC','2026-10-20 02:19:56',1,2,'2026-10-20 02:19:56','2026-10-20 02:19:56',NULL,'pengumuman','TPPBM','2026-11-06 00:00:00');
CREATE TABLE "self_development_journals" ("id" integer primary key autoincrement not null, "user_id" integer not null, "activity_date" date not null, "activity_name" varchar not null, "organizer" varchar, "speaker" varchar, "description" text not null, "reflection" text not null, "status" varchar not null default 'draft', "published_at" datetime, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("user_id") references "users"("id") on delete restrict);
INSERT INTO "self_development_journals" VALUES(1,3,'2026-10-20 00:00:00','Seminar Pendampingan Orang Muda','Komunitas katolik Indonesia','Prof Dr. Andrias Purwanto','Kegiatan ini mengembangkan diri sebagai pribadi yang berakar pada kebutuhan orang mda dalam pengenala ndiri','Sementara saya belum merefleksikan dari pengalaman ini. namun demikian bagi saya yang penting apdalah persoalan belajar. Belajar untuk menjadi diri sendiri dengan segala kesempatan berkembang meskipunn perlu perjuangan','published','2026-10-20 01:20:54','2026-10-20 01:20:54','2026-10-20 01:20:54',NULL);
