CREATE TABLE "spiritual_guidance_reports" ("id" integer primary key autoincrement not null, "user_id" integer not null, "schedule_id" integer, "mentor_name" varchar not null, "meeting_at" datetime not null, "location" varchar, "report_content" text not null, "proof_file" varchar, "status" varchar not null default 'draft', "submitted_at" datetime, "created_at" datetime, "updated_at" datetime, "deleted_at" datetime, foreign key("user_id") references "users"("id") on delete restrict, foreign key("schedule_id") references "spiritual_guidance_schedules"("id") on delete set null);
INSERT INTO "spiritual_guidance_reports" VALUES(1,3,NULL,'Br. Yohanes Subagio, FIC','2026-10-06 00:00:00','Ruang Bimbingan Ambarawa','Dalam bimbingan rohani bulan ini, saya merenungkan kembali perjalanan panggilan sebagai Bruder FIC. Saya diajak oleh pembimbing untuk lebih tekun dalam doa pribadi dan menjaga semangat pelayanan di sekolah. Semua arahan sangat meneguhkan hati saya.',NULL,'submitted','2026-10-07 16:47:15','2026-10-07 16:47:15','2026-10-07 16:47:15',NULL);
INSERT INTO "spiritual_guidance_reports" VALUES(2,3,NULL,'Br. Yohanes Subagio, FIC','2026-10-20 00:00:00','Komunitas Deltamas','Bimbingan kali ini saya diajak untk  merefleksikan diri mengenai pentingnya rendah hati. Mengarahkan diri semata hanya demi kemuliaan Tuhan. memang tidak mudah untuk dilaksanakan, namun tetap harus dijalankan sebagaimana mestinya.','logbooks/bimbingan/PpYDTOgER1HngFbIVhO1iKZURdVCxEMcxIrn7WOC.png','submitted','2026-10-20 01:16:04','2026-10-20 01:16:04','2026-10-20 01:16:04',NULL);
