INSERT INTO "wawanhati_reports" VALUES(1,3,NULL,'Br. Fransiskus Xaverius, FIC','2026-10-20 00:00:00','Solo','sementara ini memang tidak ada nabi tidak ada juga penguasa, jadi semua adalah saudara. saudara dalam panggilan pun saudara dalam menapaki perjalanan hidup yang kadang tidak mudah. Smeoga Allah yang maha baik senantiasa menyertaik kita',NULL,'submitted','2026-10-20 01:17:48','2026-10-20 01:17:48','2026-10-20 01:17:48',NULL);
